content = content.replace(/name: 'Comprehensive Evaluation ' \+ Date.now\(\)/, "name: 'Real-Time Evaluation ' + Date.now()");

// Duplicate baseQuestions to get 18 questions
content = content.replace(/const baseQuestions = \[([\s\S]*?)\];/, 'const baseQuestions = [$1, $1];');

// Change assessment loop to 10
content = content.replace(/for \(let i = 1; i <= 5; i\+\)/, 'for (let i = 1; i <= 10; i++)');

// Inside assessment loop, add PATCH settings
content = content.replace(/if \(aRes.ok\) \{([\s\S]*?)await delay\(150\);/g, `if (aRes.ok) {$1
      // Set to REAL_TIME mode and published
      await fetchWithRetry(\`\${API_BASE}/assessments/\${aData.data.id}/settings\`, {
        method: 'PATCH',
        headers: authHeaders,
        body: JSON.stringify({ mode: 'REAL_TIME', participantIdentity: 'EXTERNAL' })
      });
      // Also publish it
      await fetchWithRetry(\`\${API_BASE}/assessments/\${aData.data.id}/status\`, {
        method: 'PATCH',
        headers: authHeaders,
        body: JSON.stringify({ status: 'PUBLISHED' })
      });
    }
    await delay(150);`);

// Update Assessment name prefix
content = content.replace(/name: \`Full Exam \$\{i\}\`/, 'name: `Live Real-Time Exam ${i}`');

fs.writeFileSync('scripts/seed-realtime.js', content);

const fs = require('fs');
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
async function publishAll() {
  const API_BASE = 'http://localhost:3001/api/v1';
  const envPath = '../assessment-service/.env';
  let envContent = fs.readFileSync(envPath, 'utf8');
  const clientId = envContent.match(/API_CLIENT_ID=(.*)/)[1];
  const clientSecret = envContent.match(/API_CLIENT_SECRET=(.*)/)[1];
  const tokenRes = await fetch(`${API_BASE}/auth/token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ clientId, clientSecret, grant_type: 'client_credentials' })
  });
  const tokenData = await tokenRes.json();
  const token = tokenData.data.access_token;
  const authHeaders = { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` };

  const res = await fetch(`${API_BASE}/assessments?limit=100`, { headers: authHeaders });
  const responseData = await res.json();
  const assessments = responseData.data; 

  if (!Array.isArray(assessments)) {
    console.log("Assessments is not an array:", assessments);
    return;
  }
  for (const a of assessments) {
    if (a.status === 'DRAFT') {
      const pRes = await fetch(`${API_BASE}/assessments/${a.id}/publish`, {
        method: 'POST',
        headers: authHeaders
      });
      if (pRes.ok) console.log(`Published ${a.name}`);
      else {
        const errorData = await pRes.json();
        console.log(`Failed to publish ${a.name}:`, errorData);
      }
      await delay(100);
    }
  }
}
