const { Client } = require('pg');
const Redis = require('ioredis');
require('dotenv').config({ path: '.env.development' }); // or .env based on environment

async function reset() {
  console.log('Connecting to database...');
  const client = new Client({
    host: process.env.DB_HOST || 'localhost',
    port: process.env.DB_PORT || 5432,
    user: process.env.DB_USERNAME || 'postgres',
    password: process.env.DB_PASSWORD || 'postgres',
    database: process.env.DB_NAME || 'assessment_dev',
  });

  await client.connect();

  console.log('Fetching all table names...');
  const res = await client.query(`
    SELECT tablename
    FROM pg_tables
    WHERE schemaname = 'public'
      AND tablename != 'migrations';
  `);

  const tables = res.rows.map((row) => row.tablename);

  if (tables.length > 0) {
    const truncateQuery = `TRUNCATE TABLE "${tables.join('", "')}" CASCADE;`;
    console.log(`Truncating ${tables.length} tables...`);
    await client.query(truncateQuery);
    console.log('All tables truncated successfully.');
  } else {
    console.log('No tables found to truncate.');
  }

  await client.end();

  console.log('Flushing Redis...');
  const redis = new Redis({
    host: process.env.REDIS_HOST || 'localhost',
    port: process.env.REDIS_PORT || 6379,
  });
  await redis.flushall();
  await redis.quit();
  console.log('Redis flushed.');

  console.log('Reset complete!');
}

reset().catch((err) => {
  console.error('Reset failed:', err);
  process.exit(1);
});

const fs = require('fs');

const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function fetchWithRetry(url, options, retries = 3) {
  for (let i = 0; i < retries; i++) {
    const res = await fetch(url, options);
    if (res.status === 429) {
      console.log('Rate limited! Waiting 1s before retry...');
      await delay(1000);
      continue;
    }
    return res;
  }
  return fetch(url, options); // final attempt
}

