    if (aRes.ok) {
      console.log(`Created Self-Paced Assessment ${i} (${isPublished ? 'PUBLISHED' : 'DRAFT'}):`, aData.data.id);
      await fetchWithRetry(`${API_BASE}/assessments/${aData.data.id}/questions`, {
        method: 'PUT',
        headers: authHeaders,
        body: JSON.stringify({ questionIds: qIds })
      });
      if (isPublished) {
        await fetchWithRetry(`${API_BASE}/assessments/${aData.data.id}/publish`, {
          method: 'POST',
          headers: authHeaders
        });
      }
    }
    await delay(50);
  }

  // 7. Create 10 Real-Time Assessments
  console.log('Creating 10 Real-Time Assessments...');
  for (let i = 1; i <= 10; i++) {
    const isPublished = i <= 5; // First 5 published, last 5 draft
    const aRes = await fetchWithRetry(`${API_BASE}/topics/${topicId}/assessments`, {
      method: 'POST',
      headers: authHeaders,
      body: JSON.stringify({ name: `Live Real-Time Exam ${i}`, type: 'EXAM', description: 'Real-time mode test' })
    });
    const aData = await aRes.json();
    if (aRes.ok) {
      console.log(`Created Real-Time Assessment ${i} (${isPublished ? 'PUBLISHED' : 'DRAFT'}):`, aData.data.id);
      // Filter out manual grading types for realtime
      const rtQIds = questionObjs.filter(q => q.type !== 'SHORT_ANSWER' && q.type !== 'ESSAY').map(q => q.id);

      await fetchWithRetry(`${API_BASE}/assessments/${aData.data.id}/questions`, {
        method: 'PUT',
        headers: authHeaders,
        body: JSON.stringify({ questionIds: rtQIds })
      });

      await fetchWithRetry(`${API_BASE}/assessments/${aData.data.id}/settings`, {
        method: 'PATCH',
        headers: authHeaders,
        body: JSON.stringify({ mode: 'REAL_TIME', participantIdentity: 'EXTERNAL' })
      });

      if (isPublished) {
        await fetchWithRetry(`${API_BASE}/assessments/${aData.data.id}/publish`, {
          method: 'POST',
          headers: authHeaders
        });
      }
    }
    await delay(50);
  }

  // Update frontend .env
  const envPath = '../assessment-service/.env';
  let envContent = fs.readFileSync(envPath, 'utf8');
  envContent = envContent.replace(/API_CLIENT_ID=.*/, `API_CLIENT_ID=${clientId}`);
  envContent = envContent.replace(/API_CLIENT_SECRET=.*/, `API_CLIENT_SECRET=${clientSecret}`);
  fs.writeFileSync(envPath, envContent);
  console.log('Updated frontend .env successfully!');
}

