import { Test, TestingModule } from '@nestjs/testing';
import { CacheService } from './cache.service';
import { getRedisToken } from '@nestjs-modules/ioredis';

describe('CacheService', () => {
  let service: CacheService;
  let redisMock: any;

  beforeEach(() => {
    redisMock = {
      get: jest.fn(),
      setex: jest.fn(),
      del: jest.fn(),
      keys: jest.fn(),
    };

    service = new CacheService(redisMock);
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  describe('getOrSet', () => {
    it('should return cached value if exists', async () => {
      redisMock.get.mockResolvedValue('{"foo":"bar"}');
      const factory = jest.fn();

      const result = await service.getOrSet('key1', 60, factory);

      expect(result).toEqual({ foo: 'bar' });
      expect(redisMock.get).toHaveBeenCalledWith('key1');
      expect(factory).not.toHaveBeenCalled();
      expect(redisMock.setex).not.toHaveBeenCalled();
    });

    it('should call factory and cache value if not exists', async () => {
      redisMock.get.mockResolvedValue(null);
      const factory = jest.fn().mockResolvedValue({ foo: 'baz' });

      const result = await service.getOrSet('key2', 60, factory);

      expect(result).toEqual({ foo: 'baz' });
      expect(redisMock.get).toHaveBeenCalledWith('key2');
      expect(factory).toHaveBeenCalled();
      expect(redisMock.setex).toHaveBeenCalledWith('key2', 60, '{"foo":"baz"}');
    });

    it('should propagate factory error and not cache anything', async () => {
      redisMock.get.mockResolvedValue(null);
      const error = new Error('Factory Failed');
      const factory = jest.fn().mockRejectedValue(error);

      await expect(service.getOrSet('key3', 60, factory)).rejects.toThrow(
        'Factory Failed',
      );

      expect(redisMock.get).toHaveBeenCalledWith('key3');
      expect(factory).toHaveBeenCalled();
      expect(redisMock.setex).not.toHaveBeenCalled();
    });

    it('should propagate JSON.parse error if cache is corrupted', async () => {
      redisMock.get.mockResolvedValue('invalid json');
      const factory = jest.fn();

      await expect(service.getOrSet('key4', 60, factory)).rejects.toThrow(
        SyntaxError,
      );

      expect(redisMock.get).toHaveBeenCalledWith('key4');
      expect(factory).not.toHaveBeenCalled();
    });

    it('should propagate redis get error', async () => {
      redisMock.get.mockRejectedValue(new Error('Redis Get Error'));
      const factory = jest.fn();

      await expect(service.getOrSet('key5', 60, factory)).rejects.toThrow(
        'Redis Get Error',
      );
      expect(factory).not.toHaveBeenCalled();
    });

    it('should propagate redis setex error', async () => {
      redisMock.get.mockResolvedValue(null);
      redisMock.setex.mockRejectedValue(new Error('Redis Set Error'));
      const factory = jest.fn().mockResolvedValue('val');

      await expect(service.getOrSet('key6', 60, factory)).rejects.toThrow(
        'Redis Set Error',
      );
    });
  });

  describe('invalidate', () => {
    it('should do nothing if keys are empty', async () => {
      await service.invalidate();
      expect(redisMock.del).not.toHaveBeenCalled();
    });

    it('should call redis del with keys', async () => {
      redisMock.del.mockResolvedValue(2);
      await service.invalidate('k1', 'k2');
      expect(redisMock.del).toHaveBeenCalledWith('k1', 'k2');
    });

    it('should propagate redis del error', async () => {
      redisMock.del.mockRejectedValue(new Error('Redis Del Error'));
      await expect(service.invalidate('k1')).rejects.toThrow('Redis Del Error');
    });
  });

  describe('invalidatePattern', () => {
    it('should do nothing if no keys match pattern', async () => {
      redisMock.keys.mockResolvedValue([]);
      await service.invalidatePattern('prefix:*');
      expect(redisMock.keys).toHaveBeenCalledWith('prefix:*');
      expect(redisMock.del).not.toHaveBeenCalled();
    });

    it('should call redis del with matched keys', async () => {
      redisMock.keys.mockResolvedValue(['prefix:1', 'prefix:2']);
      redisMock.del.mockResolvedValue(2);
      await service.invalidatePattern('prefix:*');
      expect(redisMock.keys).toHaveBeenCalledWith('prefix:*');
      expect(redisMock.del).toHaveBeenCalledWith('prefix:1', 'prefix:2');
    });

    it('should propagate redis keys error', async () => {
      redisMock.keys.mockRejectedValue(new Error('Redis Keys Error'));
      await expect(service.invalidatePattern('prefix:*')).rejects.toThrow(
        'Redis Keys Error',
      );
      expect(redisMock.del).not.toHaveBeenCalled();
    });

    it('should propagate redis del error during invalidatePattern', async () => {
      redisMock.keys.mockResolvedValue(['prefix:1']);
      redisMock.del.mockRejectedValue(new Error('Redis Del Error'));
      await expect(service.invalidatePattern('prefix:*')).rejects.toThrow(
        'Redis Del Error',
      );
    });
  });
});

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';

@Injectable()
export class TransformInterceptor<T> implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const ctx = context.switchToHttp();
    const response = ctx.getResponse();
    const request = ctx.getRequest();

    return next.handle().pipe(
      map((result) => {
        const baseResponse = {
          success: true,
          statusCode: response.statusCode,
          timestamp: new Date().toISOString(),
          path: request.url,
        };

        // Case 1: Paginated responses
        if (result && result.meta && Array.isArray(result.data)) {
          return {
            ...baseResponse,
            meta: result.meta,
            data: this.sanitizeData(result.data),
          };
        }

        // Case 2: Standard single object responses
        return {
          ...baseResponse,
          data:
            result !== undefined && result !== null
              ? this.sanitizeData(result)
              : { message: 'Action executed successfully' },
        };
      }),
    );
  }

  // CENTRALIZED SAFETY NET: Strips internal tenant keys from output payloads
  private sanitizeData(data: any): any {
    if (!data) return data;

    // Handle array collections recursively
    if (Array.isArray(data)) {
      return data.map((item) => this.sanitizeData(item));
    }

    // Process object properties safely
    if (typeof data === 'object') {
      // Create a shallow copy to prevent mutation errors
      const cleaned = { ...data };

      // Enforce removal of sensitive columns explicitly
      delete cleaned.deletedAt;

      return cleaned;
    }

    return data;
  }
}

import { NestFactory, Reflector } from '@nestjs/core';
import { AppModule } from './app.module';
import { ClassSerializerInterceptor, ValidationPipe } from '@nestjs/common';
import { HttpExceptionFilter } from './common/filters/http-exception.filter';
import { ThrottlerExceptionFilter } from './common/filters/throttler-exception.filter';
import { TransformInterceptor } from './common/interceptors/transform.interceptor';
import { IoAdapter } from '@nestjs/platform-socket.io';
import { SwaggerModule, DocumentBuilder } from '@nestjs/swagger';
import helmet from 'helmet';

async function bootstrap() {
  const app = await NestFactory.create(AppModule, {
    logger: ['error', 'warn', 'log', 'debug'],
  });

  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
    }),
  );

  app.useWebSocketAdapter(new IoAdapter(app));

  app.setGlobalPrefix('api/v1');

  // Global error formatting filter
  app.useGlobalFilters(
    new HttpExceptionFilter(),
    new ThrottlerExceptionFilter(),
  );

  // Global success formatting interceptor
  app.useGlobalInterceptors(
    new TransformInterceptor(),
    new ClassSerializerInterceptor(app.get(Reflector)),
  );

  const config = new DocumentBuilder()
    .setTitle('FSA Assessment Service API')
    .setDescription(
      `
      ## Authentication
      All standard endpoints require a Bearer token obtained from \`POST /auth/token\`.
      Administrative endpoints require the \`x-admin-api-key\` header.

      ## Rate Limits
      - Auth endpoint: 10 requests/minute per clientId
      - Read endpoints: 500 requests/minute per clientId
      - Write endpoints: 200 requests/minute per clientId

      Exceeded limits return \`429 Too Many Requests\` with a \`Retry-After\` header.

      ## Error Format
      All errors follow this shape:
      \`\`\`json
      {
        "statusCode": 404,
        "error": "NOT_FOUND",
        "message": "Assessment abc-123 not found",
        "path": "/api/v1/assessments/abc-123",
        "timestamp": "2026-01-15T09:23:01.123Z"
      }
      \`\`\`
        `,
    )
    .setVersion('1.0')
    .addTag('Health')
    .addTag('Auth')
    .addTag('Clients')
    .addTag('Topics')
    .addTag('Questions')
    .addTag('Question Banks')
    .addTag('Assessments')
    .addTag('Participants')
    .addTag('Runtime')
    .addTag('Realtime')
    .addTag('Reports')
    .addBearerAuth()
    .addApiKey(
      { type: 'apiKey', in: 'header', name: 'x-admin-api-key' },
      'x-admin-api-key',
    )
    .build();
  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api/docs', app, document);

  // Helmet — disable COEP/CORP in dev so they don't fight with CORS
  app.use(
    helmet({
      crossOriginResourcePolicy: { policy: 'cross-origin' },
    }),
  );

  const allowedOrigins =
    process.env.NODE_ENV === 'production'
      ? (process.env.ALLOWED_ORIGINS ?? '')
          .split(',')
          .map((o) => o.trim())
          .filter(Boolean)
      : ['http://localhost:3001', 'https://app.apidog.com'];

  app.enableCors({
    origin:
      allowedOrigins.length > 0 ? allowedOrigins : ['http://localhost:3000'],
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization', 'x-admin-api-key'],
    credentials: true,
  });

  await app.listen(process.env.PORT ?? 3001);
}
bootstrap();

