  @Patch(':id/suspend')
  @SuperAdmin()
  @ApiSecurity('x-admin-api-key')
  @ApiOperation({ summary: '[Admin] Suspend a client' })
  @ApiParam({ name: 'id', description: 'Client UUID' })
