import {
  BadRequestException,
  Injectable,
  NotFoundException,
  Logger,
  HttpException,
  InternalServerErrorException,
} from '@nestjs/common';
import { QuestionBankRepository } from './repositories/question-bank.repository';
import { CreateQuestionBankDto } from './dto/create-question-bank.dto';
import { PaginationQueryDto } from '../../common/dto/pagination-query.dto';
import { UpdateQuestionBankDto } from './dto/update-question-bank.dto';
import { TopicRepository } from '../topics/repositories/topic.repository';
import { QuestionBankQuestion } from './entities/question-bank-question.entity';
import { QuestionBankQuestionRepository } from './repositories/question-bank-question.repository';

@Injectable()
export class QuestionBanksService {
  private readonly logger = new Logger(QuestionBanksService.name);

  constructor(
    private readonly bankRepository: QuestionBankRepository,
    private readonly topicRepository: TopicRepository,
    private readonly bankQuestionRepository: QuestionBankQuestionRepository,
  ) {}

  async create(dto: CreateQuestionBankDto) {
    try {
      const exists = await this.bankRepository.findOne({
        name: dto.name,
      });
      if (exists)
        throw new BadRequestException(
          'A question bank with this name already exists',
        );

      const savedBank = await this.bankRepository.create({
        ...dto,
      });

      const mapped = {
        ...savedBank,
        questionCount: 0,
      } as any;
      delete mapped.clientId;
      return mapped;
    } catch (error) {
      if (error instanceof BadRequestException) throw error;
      throw new BadRequestException('Failed to create question bank');
    }
  }

  async findAll(query: PaginationQueryDto) {
    try {
      const [banks, total] = await this.bankRepository.findPaginated(
        query,
        ['name', 'description'],
        ['questions', 'topic'],
      );

      const mappedData = banks.map((bank: any) => ({
        ...bank,
        questionCount: bank.questions?.length || 0,
      }));

      mappedData.forEach((m) => {
        delete m.questions;
        delete m.topicId;
        delete m.clientId;
      });

      return {
        data: mappedData,
        meta: {
          total,
          page: query.page,
          limit: query.limit,
          pageCount: Math.ceil(total / query.limit),
        },
      };
    } catch (error) {
      throw new BadRequestException('Could not fetch question banks');
    }
  }

  async createTopicBank(topicId: string, dto: CreateQuestionBankDto) {
    try {
      const exists = await this.bankRepository.findOne({
        name: dto.name,
      });
      if (exists)
        throw new BadRequestException(
          'A question bank with this name already exists',
        );

      const topic = await this.topicRepository.findById(topicId);
      if (!topic) throw new NotFoundException('Topic not found');

      const savedBank = await this.bankRepository.create({
        ...dto,
        topic: { id: topic.id },
      });

      const mapped = {
        ...savedBank,
        questionCount: 0,
      } as any;
      delete mapped.clientId;
      return mapped;
    } catch (error) {
      if (
        error instanceof BadRequestException ||
        error instanceof NotFoundException
      )
        throw error;
      throw new BadRequestException('Failed to create question bank');
    }
  }

  async findTopicBanks(topicId: string, query: PaginationQueryDto) {
    try {
      query.topicId = topicId;
      const [banks, total] = await this.bankRepository.findPaginated(
        query,
        ['name', 'description'],
        ['questions', 'topic'],
      );

      const mappedData = banks.map((bank: any) => ({
        ...bank,
        questionCount: bank.questions?.length || 0,
      }));

      // Cleanup
      mappedData.forEach((m) => {
        delete m.questions;
        delete m.topicId;
        delete m.clientId;
      });

      return {
        data: mappedData,
        meta: {
          total,
          page: query.page,
          limit: query.limit,
          pageCount: Math.ceil(total / query.limit),
          topicId,
        },
      };
    } catch (error) {
      throw new BadRequestException('Could not fetch question banks');
    }
  }

  async findById(id: string) {
    try {
      const bank: any = await this.bankRepository.findById(id, [
        'questions',
        'topic',
      ]);
      if (!bank) throw new NotFoundException('Question bank not found');

      bank.questionCount = bank.questions?.length || 0;
      delete bank.questions;
      delete bank.topicId;
      delete bank.clientId;

      return bank;
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new BadRequestException('Question bank not found');
    }
  }

  async update(id: string, dto: UpdateQuestionBankDto) {
    try {
      await this.findById(id);

      if (dto.name) {
        const exists = await this.bankRepository.findOne({
          name: dto.name,
        });
        if (exists && exists.id !== id) {
          throw new BadRequestException(
            'This question bank name is already taken',
          );
        }
      }

      await this.bankRepository.update({ id }, { ...dto });
      return await this.findById(id);
    } catch (error) {
      if (
        error instanceof NotFoundException ||
        error instanceof BadRequestException
      )
        throw error;
      throw new BadRequestException('Update failed');
    }
  }

  async delete(id: string) {
    try {
      await this.findById(id);
      await this.bankRepository.softDelete({ id });
      return;
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new BadRequestException('Delete failed');
    }
  }

  async getBankQuestions(bankId: string, query: PaginationQueryDto) {
    try {
      const bank = await this.findById(bankId);
      if (!bank) throw new NotFoundException('Bank not found');

      const [junctions, total] = await this.bankQuestionRepository.findByBank(
        bankId,
        query.page,
        query.limit,
      );

      return {
        data: junctions.map((j) => ({
          id: j.question.id,
          questionText: j.question.questionText,
          type: j.question.type,
          difficulty: j.question.difficulty,
          points: j.question.points,
          options: j.question.options,
          correctAnswers: j.question.correctAnswer,
          createdAt: j.question.createdAt,
          updatedAt: j.question.updatedAt,
        })),
        meta: {
          total,
          page: query.page,
          limit: query.limit,
          pageCount: Math.ceil(total / query.limit),
          bankId,
        },
      };
    } catch (error) {
      if (error instanceof HttpException) throw error;
      this.logger.error('getBankQuestions error:', error);
      throw new InternalServerErrorException('Failed to get bank questions');
    }
  }

  async addQuestionToBank(bankId: string, questionId: string) {
    try {
      const bank = await this.findById(bankId);
      if (!bank) throw new NotFoundException('Bank not found');

      // Check not already added
      const existing =
        await this.bankQuestionRepository.findOneByBankAndQuestion(
          bankId,
          questionId,
        );
      if (existing)
        throw new BadRequestException('Question already in this bank');

      await this.bankQuestionRepository.save({
        questionBankId: bankId,
        questionId: questionId,
      });

      return {
        bankId,
        questionId,
        addedAt: new Date().toISOString(),
      };
    } catch (error) {
      throw new BadRequestException('Failed to add question to bank');
    }
  }

  async addQuestionsToBank(bankId: string, questionIds: string[]) {
    try {
      const bank = await this.findById(bankId);
      if (!bank) throw new NotFoundException('Bank not found');

      // Filter out already existing ones
      const existing = await Promise.all(
        questionIds.map((qid) =>
          this.bankQuestionRepository.findOneByBankAndQuestion(bankId, qid),
        ),
      );

      const newIds = questionIds.filter((_, i) => !existing[i]);

      if (newIds.length === 0) {
        throw new BadRequestException('All questions are already in this bank');
      }

      await Promise.all(
        newIds.map((questionId) =>
          this.bankQuestionRepository.save({
            questionBankId: bankId,
            questionId: questionId,
          } as any),
        ),
      );

      return {
        bankId,
        questionIds: newIds,
        addedCount: newIds.length,
        addedAt: new Date().toISOString(),
      };
    } catch (error) {
      if (error instanceof NotFoundException) throw error;
      throw new BadRequestException('Failed to add questions to bank');
    }
  }

  async removeQuestionFromBank(bankId: string, questionId: string) {
    try {
      // find the junction record first
      const junction =
        await this.bankQuestionRepository.findOneByBankAndQuestion(
          bankId,
          questionId,
        );

      if (!junction) {
        throw new NotFoundException('Question not found in this bank');
      }

      // soft delete - sets deletedAt, excluded by findByBank
      await this.bankQuestionRepository.softDelete({ id: junction.id });

      return {
        bankId,
        questionId,
        removedAt: new Date().toISOString(),
      };
    } catch (error) {
      if (error instanceof HttpException) throw error;
      this.logger.error('removeQuestionFromBank error:', error);
      throw new InternalServerErrorException('Failed to remove question');
    }
  }
}

// src/modules/questions/question.service.ts
import {
  Injectable,
  BadRequestException,
  NotFoundException,
  Logger,
  HttpException,
  InternalServerErrorException,
} from '@nestjs/common';
import { instanceToPlain } from 'class-transformer';
import { QuestionRepository } from './repositories/question.repository';
import { TopicRepository } from '../topics/repositories/topic.repository';
import { QuestionBankRepository } from '../question-banks/repositories/question-bank.repository';
import { QUESTION_TYPES_CONFIG } from './constants/question-types.config';
import { CreateQuestionDto } from './dto/create-question.dto';
import { PaginationQueryDto } from '@common/dto/pagination-query.dto';
import { UpdateQuestionDto } from './dto/update-question.dto';

@Injectable()
export class QuestionsService {
  private readonly logger = new Logger(QuestionsService.name);

  constructor(
    private readonly questionRepository: QuestionRepository,
    private readonly topicRepository: TopicRepository,
    private readonly bankRepository: QuestionBankRepository,
  ) {}

  private transformResponse(question: unknown): Record<string, unknown> | null {
    if (!question) return null;

    // Use instanceToPlain to respect @Exclude() decorators on the entity
    const plain = instanceToPlain(question);

    const mapped: Record<string, unknown> = {
      ...plain,
    };

    // API previously expected `text`, but user requested `questionText`
    // We just leave mapped.questionText as is.

    // No longer need to unpack — entity column is now `options` directly
    // Just keep mapped.options as-is from the entity

    if (mapped.correctAnswer !== undefined) {
      mapped.correctAnswers = mapped.correctAnswer;
      delete mapped.correctAnswer;
    }

    // Keep the topic object as requested, do not flatten it into topicId
    // and remove topicId if it somehow exists
    if (mapped.topicId) {
      delete mapped.topicId;
    }

    return mapped;
  }

  async createTopicQuestion(topicId: string, dto: CreateQuestionDto) {
    try {
      console.log('createTopicQuestion DTO:', JSON.stringify(dto, null, 2));
      const typeConfig = QUESTION_TYPES_CONFIG[dto.type];
      if (!typeConfig) {
        throw new BadRequestException(
          `Invalid question type specified: [${dto.type}]`,
        );
      }

      // Verify topic exists
      const topic = await this.topicRepository.findById(topicId);
      if (!topic) throw new NotFoundException('Topic not found');

      const saved = await this.questionRepository.create({
        questionText: dto.questionText,
        type: dto.type,
        difficulty: dto.difficulty,
        points: dto.points !== undefined ? dto.points : 1,
        topic: { id: topic.id },
        options: (dto.options as Record<string, unknown>[]) || [],
        correctAnswer: dto.correctAnswers as unknown as Record<string, unknown>,
      } as any);

      return this.transformResponse(saved);
    } catch (error) {
      if (error instanceof HttpException) throw error;
      this.logger.error('createTopicQuestion error:', error);
      throw new InternalServerErrorException('Failed to create question');
    }
  }

  async findAll(query: PaginationQueryDto) {
    try {
      const [questions, total] = await this.questionRepository.findPaginated(
        query,
        ['questionText'],
        ['topic'],
      );

      return {
        data: questions.map((q) => this.transformResponse(q)),
        meta: {
          total,
          page: query.page,
          limit: query.limit,
          pageCount: Math.ceil(total / query.limit),
        },
      };
    } catch (error) {
      if (error instanceof HttpException) throw error;
      this.logger.error('findAll questions error:', error);
      throw new InternalServerErrorException('Could not fetch questions');
    }
  }

  async findTopicQuestions(topicId: string, query: PaginationQueryDto) {
    try {
      // Force filter by topicId
      query.topicId = topicId;

      const [questions, total] = await this.questionRepository.findPaginated(
        query,
        ['questionText'],
        ['topic'],
      );

      return {
        data: questions.map((q) => this.transformResponse(q)),
        meta: {
          total,
          page: query.page,
          limit: query.limit,
          pageCount: Math.ceil(total / query.limit),
          topicId,
        },
      };
    } catch (error) {
      if (error instanceof HttpException) throw error;
      this.logger.error('findTopicQuestions error:', error);
      throw new InternalServerErrorException('Could not fetch questions');
    }
  }

  async findById(id: string) {
    try {
      const question = await this.questionRepository.findById(id, ['topic']);
      if (!question) throw new NotFoundException('Question not found');
      return this.transformResponse(question);
    } catch (error) {
      if (error instanceof HttpException) throw error;
      this.logger.error('findById error:', error);
      throw new InternalServerErrorException('Question not found');
    }
  }

  async update(id: string, dto: UpdateQuestionDto) {
    try {
      const question = await this.questionRepository.findById(id);
      if (!question) throw new NotFoundException('Question not found');

      const updateData: Record<string, unknown> = {};
      if (dto.questionText !== undefined)
        updateData.questionText = dto.questionText;
      if (dto.type !== undefined) updateData.type = dto.type;
      if (dto.difficulty !== undefined) updateData.difficulty = dto.difficulty;
      if (dto.points !== undefined) updateData.points = dto.points;
      if (dto.options !== undefined) updateData.options = dto.options;
      if (dto.correctAnswers !== undefined)
        updateData.correctAnswer = dto.correctAnswers;

      await this.questionRepository.update({ id }, updateData);
      return this.findById(id);
    } catch (error) {
      if (error instanceof HttpException) throw error;
      this.logger.error('Update question error:', error);
      throw new InternalServerErrorException('Update failed');
    }
  }

  async delete(id: string) {
    try {
      await this.findById(id);
      await this.questionRepository.softDelete({ id });
      return;
    } catch (error) {
      if (error instanceof HttpException) throw error;
      this.logger.error('Delete error:', error);
      throw new InternalServerErrorException('Delete failed');
    }
  }
}

import {
  WebSocketGateway,
  WebSocketServer,
  SubscribeMessage,
  MessageBody,
  ConnectedSocket,
  OnGatewayDisconnect,
  OnGatewayInit,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { Logger } from '@nestjs/common';
import { RealtimeSessionService } from '../services/realtime-session.service';
import { RealtimeEvents } from '../constants/realtime.events';
import { JoinRoomDto, RoomRole } from '../dto/join-room.dto';
import { StartQuestionDto } from '../dto/start-question.dto';
import { SubmitAnswerDto } from '../dto/submit-answer.dto';
import { UseInterceptors } from '@nestjs/common';
import { WsClientContextInterceptor } from '../../../common/interceptors/ws-client-context.interceptor';
import { OnEvent } from '@nestjs/event-emitter';
import { clientStorage } from '../../../common/context/client.storage';

@UseInterceptors(WsClientContextInterceptor)
@WebSocketGateway({
  cors: {
    origin: '*',
    credentials: true,
  },
  namespace: '/realtime',
})
export class RealtimeGateway implements OnGatewayInit, OnGatewayDisconnect {
  @WebSocketServer()
  private server!: Server;

  private readonly logger = new Logger(RealtimeGateway.name);

  // socketId → assessmentId (for disconnect handling)
  private readonly socketRooms = new Map<string, string>();

  constructor(private readonly sessionService: RealtimeSessionService) {}

  afterInit() {
    this.logger.log('RealtimeGateway initialized');
  }

  private async withContext<T>(
    assessmentId: string,
    fn: () => Promise<T>,
  ): Promise<T> {
    const session = await this.sessionService['redis'].getSession(assessmentId);
    this.logger.log(
      `withContext: assessmentId=${assessmentId}, session=${!!session}, clientId=${session?.clientId || 'NONE'}`,
    );
    if (session && session.clientId) {
      return clientStorage.run({ clientId: session.clientId }, fn);
    }
    this.logger.warn(
      `withContext: No clientId found for assessmentId=${assessmentId}, running without context`,
    );
    return fn();
  }

  // ---------------------------------------------------------------------------
  // ADMIN DASHBOARD
  // ---------------------------------------------------------------------------

  @SubscribeMessage('JOIN_ADMIN_ROOM')
  handleJoinAdminRoom(
    @ConnectedSocket() socket: Socket,
    @MessageBody() data: { clientId: string },
  ) {
    if (data?.clientId) {
      socket.join(`admin_assessments_${data.clientId}`);
      this.logger.log(
        `Socket ${socket.id} joined admin room for client ${data.clientId}`,
      );
    }
  }

  @OnEvent('assessment.status.updated')
  handleAssessmentStatusUpdated(payload: {
    clientId: string;
    assessmentId: string;
    status: string;
  }) {
    this.server
      .to(`admin_assessments_${payload.clientId}`)
      .emit('ASSESSMENT_UPDATED', payload);
    this.logger.log(
      `Broadcasted ASSESSMENT_UPDATED for assessment ${payload.assessmentId} (client: ${payload.clientId})`,
    );
  }

  // ---------------------------------------------------------------------------
  // JOIN_ROOM
  // ---------------------------------------------------------------------------

  @SubscribeMessage(RealtimeEvents.JOIN_ROOM)
  async handleJoinRoom(
    @ConnectedSocket() socket: Socket,
    @MessageBody() dto: JoinRoomDto,
  ) {
    try {
      const assessmentId = dto.roomId;

      await this.withContext(assessmentId, async () => {
        await socket.join(assessmentId);
        this.socketRooms.set(socket.id, assessmentId);

        const result = await this.sessionService.joinRoom(
          assessmentId,
          socket.id,
          dto.participantId ?? null,
          dto.role,
          dto.name ?? null,
        );

        this.server.to(assessmentId).emit(RealtimeEvents.ROOM_UPDATE, {
          count: result.count,
          participants: result.participants,
        });

        this.logger.log(`${dto.role} ${socket.id} joined room ${assessmentId}`);

        // Reconnect resilience for participants
        if (dto.role === RoomRole.PARTICIPANT) {
          const session =
            await this.sessionService['redis'].getSession(assessmentId);
          if (
            session &&
            session.status === 'active' &&
            session.currentQuestionId
          ) {
            const endTimeStr = session.questionEndTime;
            const endTime = endTimeStr ? new Date(endTimeStr).getTime() : 0;
            const now = Date.now();

            if (endTime > now) {
              const questions =
                await this.sessionService[
                  'assessmentQuestions'
                ].findByAssessment(assessmentId);
              const targetQuestion = questions.find(
                (q: any) => q.id === session.currentQuestionId,
              );

              if (targetQuestion) {
                const snapshot = targetQuestion.questionSnapshot as any;
                const options = this.sessionService['buildOptions'](snapshot);

                socket.emit(RealtimeEvents.NEW_QUESTION, {
                  questionNumber: session.currentQuestionIndex + 1,
                  totalQuestions: session.totalQuestions,
                  q: {
                    id: snapshot.id,
                    assessmentQuestionId: targetQuestion.id,
                    type: snapshot.type,
                    questionText: snapshot.questionText,
                    difficulty: snapshot.difficulty,
                    points: targetQuestion.points,
                  },
                  options,
                  endTime: new Date(endTime).toISOString(),
                });
                this.logger.log(
                  `Resent active question to reconnecting participant ${socket.id}`,
                );
              }
            }
          }
        }
      });
    } catch (error) {
      socket.emit(RealtimeEvents.ERROR, {
        event: RealtimeEvents.JOIN_ROOM,
        message: (error as Error).message,
      });
    }
  }

  // ---------------------------------------------------------------------------
  // START_Q
  // ---------------------------------------------------------------------------

  @SubscribeMessage(RealtimeEvents.START_Q)
  async handleStartQuestion(
    @ConnectedSocket() socket: Socket,
    @MessageBody() dto: StartQuestionDto,
  ) {
    try {
      const assessmentId = this.socketRooms.get(socket.id);
      if (!assessmentId) throw new Error('Not in a room');

      await this.withContext(assessmentId, async () => {
        const session =
          await this.sessionService['redis'].getSession(assessmentId);
        if (session?.status === 'active' && session.currentQuestionId) {
          await this.endCurrentQuestion(assessmentId);
        }

        try {
          const questionData = await this.sessionService.startQuestion(
            assessmentId,
            socket.id,
            dto.questionId,
          );

          this.server
            .to(assessmentId)
            .emit(RealtimeEvents.NEW_QUESTION, questionData);

          this.logger.log(
            `Question ${questionData.questionNumber}/${questionData.totalQuestions} started in room ${assessmentId}`,
          );
        } catch (err: any) {
          if (err.message === 'No more questions') {
            await this.endSession(assessmentId);
          } else {
            throw err;
          }
        }
      });
    } catch (error) {
      socket.emit(RealtimeEvents.ERROR, {
        event: RealtimeEvents.START_Q,
        message: (error as Error).message,
      });
    }
  }

  // ---------------------------------------------------------------------------
  // REVEAL_ANSWERS
  // ---------------------------------------------------------------------------

  @SubscribeMessage(RealtimeEvents.REVEAL_ANSWERS)
  async handleRevealAnswers(
    @ConnectedSocket() socket: Socket,
    @MessageBody() data?: { roomId?: string },
  ) {
    try {
      const assessmentId = this.socketRooms.get(socket.id) ?? data?.roomId;
      if (!assessmentId) throw new Error('Not in a room');

      await this.withContext(assessmentId, async () => {
        const session =
          await this.sessionService['redis'].getSession(assessmentId);
        if (!session?.isPreview && session?.hostSocketId !== socket.id) {
          throw new Error('Only the host can reveal answers');
        }

        if (session?.status === 'active' && session.currentQuestionId) {
          await this.endCurrentQuestion(assessmentId);
        }
      });
    } catch (error) {
      socket.emit(RealtimeEvents.ERROR, {
        event: RealtimeEvents.REVEAL_ANSWERS,
        message: (error as Error).message,
      });
    }
  }

  // ---------------------------------------------------------------------------
  // SUBMIT_ANS
  // ---------------------------------------------------------------------------

  @SubscribeMessage(RealtimeEvents.SUBMIT_ANS)
  async handleSubmitAnswer(
    @ConnectedSocket() socket: Socket,
    @MessageBody() dto: SubmitAnswerDto,
  ) {
    try {
      const assessmentId = this.socketRooms.get(socket.id);
      if (!assessmentId) throw new Error('Not in a room');

      await this.withContext(assessmentId, async () => {
        const members =
          await this.sessionService['redis'].getMembers(assessmentId);
        const member = members.find((m) => m.socketId === socket.id);
        if (!member?.participantId) {
          socket.emit(RealtimeEvents.ERROR, {
            event: RealtimeEvents.SUBMIT_ANS,
            message: 'Participant not found in room',
          });
          return;
        }

        const session =
          await this.sessionService['redis'].getSession(assessmentId);
        if (!session || !session.currentQuestionId)
          throw new Error('No active question');

        const result = await this.sessionService.submitAnswer(
          assessmentId,
          member.participantId,
          session.currentQuestionId,
          dto.choice,
          dto.response,
          dto.timeTaken,
        );

        if (!result.stored) {
          return;
        }

        const hostSession =
          await this.sessionService['redis'].getSession(assessmentId);
        if (hostSession?.hostSocketId) {
          this.server
            .to(hostSession.hostSocketId)
            .emit(RealtimeEvents.ROOM_UPDATE, {
              event: 'answer:received',
              totalAnswered: result.totalAnswered,
              totalParticipants: result.totalParticipants,
            });
        }

        if (result.totalAnswered >= result.totalParticipants) {
          await this.endCurrentQuestion(assessmentId);
        }
      });
    } catch (error) {
      socket.emit(RealtimeEvents.ERROR, {
        event: RealtimeEvents.SUBMIT_ANS,
        message: (error as Error).message,
      });
    }
  }

  // ---------------------------------------------------------------------------
  // DISCONNECT
  // ---------------------------------------------------------------------------

  async handleDisconnect(socket: Socket) {
    const assessmentId = this.socketRooms.get(socket.id);
    if (!assessmentId) return;

    try {
      const result = await this.sessionService.handleDisconnect(
        socket.id,
        assessmentId,
      );

      this.server.to(assessmentId).emit(RealtimeEvents.ROOM_UPDATE, {
        count: result.count,
        participants: result.participants,
      });

      this.socketRooms.delete(socket.id);
    } catch {
      // Session may already be ended
    }
  }

  // ---------------------------------------------------------------------------
  // PRIVATE HELPERS
  // ---------------------------------------------------------------------------

  private async endCurrentQuestion(assessmentId: string): Promise<void> {
    try {
      const results = await this.sessionService.endQuestion(assessmentId);

      let correctStr = '';
      if (results.correctAnswer) {
        correctStr =
          results.correctAnswer.optionId ||
          results.correctAnswer.value?.toString() ||
          JSON.stringify(results.correctAnswer);
      }

      this.server.to(assessmentId).emit(RealtimeEvents.Q_RESULTS, {
        correct: correctStr,
        stats: results.stats,
      });

      const rankData = await this.sessionService.getRankData(assessmentId);
      const members =
        await this.sessionService['redis'].getMembers(assessmentId);

      for (const member of members) {
        if (member.role === 'participant' && member.participantId) {
          const myRank = await this.sessionService['redis'].getParticipantRank(
            assessmentId,
            member.participantId,
          );

          this.server.to(member.socketId).emit(RealtimeEvents.SHOW_RANK, {
            top5: rankData.top5,
            myRank,
          });
        } else if (member.role === 'host') {
          this.server.to(member.socketId).emit(RealtimeEvents.SHOW_RANK, {
            top5: rankData.top5,
            myRank: null,
          });
        }
      }
    } catch (error) {
      this.logger.error(
        `Failed to end question in room ${assessmentId}`,
        error,
      );
    }
  }

  private async endSession(assessmentId: string): Promise<void> {
    try {
      const { leaderboard } =
        await this.sessionService.endSession(assessmentId);

      this.server
        .to(assessmentId)
        .emit(RealtimeEvents.SHOW_FINAL_RANK, leaderboard);
      this.server
        .to(assessmentId)
        .emit(RealtimeEvents.SESSION_ENDED, { assessmentId });

      this.logger.log(`Session ended for assessment ${assessmentId}`);
    } catch (error) {
      this.logger.error(
        `Failed to end session for assessment ${assessmentId}`,
        error,
      );
    }
  }
}

