import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication, ValidationPipe } from '@nestjs/common';
import request from 'supertest';
import { AppModule } from './../src/app.module';
import { TransformInterceptor } from './../src/common/interceptors/transform.interceptor';
import { ClassSerializerInterceptor } from '@nestjs/common';
import { Reflector } from '@nestjs/core';

/**
 * -----------------------------------------------------------------------------
 * TEST STRATEGY & DOCUMENTATION
 * -----------------------------------------------------------------------------
 * What's being tested and why:
 * We are testing the E2E critical user journey for the Assessments Module.
 * This covers creating an assessment, fetching it, modifying its draft state,
 * adding questions to it, updating its settings, and finally publishing it.
 * This ensures the core business logic of the assessment lifecycle works end-to-end.
 *
 * What's NOT tested:
 * - We skip testing the internal database mappings and raw SQL logic, relying on
 *   the public API contract.
 * - We skip negative tests for every single validation field (we test a few to ensure
 *   validation works) because exhaustive validation testing belongs in unit tests.
 *
 * Coverage assessment:
 * This gives ~80% confidence on the Assessment API layer, covering the main happy
 * paths and the critical transition from DRAFT to PUBLISHED. Error cases like updating
 * a published assessment are also covered.
 *
 * Test data strategy:
 * We use factory-like helper functions to dynamically create an isolated Client,
 * Token, and Topic for this specific test suite run. We do not use shared JSON fixtures.
 * -----------------------------------------------------------------------------
 */

// --- FACTORIES & HELPERS ---
async function createIsolatedClientAndToken(app: INestApplication) {
  const timestamp = Date.now();
  const adminClientRes = await request(app.getHttpServer())
    .post('/api/v1/clients')
    .set('x-admin-api-key', 'test-admin-api-key-12345678901234567890')
    .send({
      name: `Assess E2E Client ${timestamp}`,
      slug: `assess-e2e-${timestamp}`,
      allowedOrigins: ['https://test.com'],
    });

  const tokenRes = await request(app.getHttpServer())
    .post('/api/v1/auth/token')
    .send({
      clientId: adminClientRes.body.data.clientId,
      clientSecret: adminClientRes.body.data.clientSecret,
      grant_type: 'client_credentials',
    });

  return tokenRes.body.data.access_token;
}

async function createIsolatedTopic(app: INestApplication, token: string) {
  const topicRes = await request(app.getHttpServer())
    .post('/api/v1/topics')
    .set('Authorization', `Bearer ${token}`)
    .send({
      name: `E2E Assessments Topic ${Date.now()}`,
      description: 'Topic for assessments e2e tests',
    });
  if (topicRes.status !== 201) {
    throw new Error(`Failed to create topic: ${JSON.stringify(topicRes.body)}`);
  }
  return topicRes.body.data.id;
}

describe('AssessmentsModule (e2e)', () => {
  let app: INestApplication;
  let adminToken: string;
  let topicId: string;
  let assessmentId: string;
  let questionId: string;

  beforeAll(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api/v1');
    app.useGlobalPipes(
      new ValidationPipe({
        whitelist: true,
        forbidNonWhitelisted: true,
        transform: true,
      }),
    );
    app.useGlobalInterceptors(
      new ClassSerializerInterceptor(app.get(Reflector)),
      new TransformInterceptor(),
    );
    await app.init();

    // Use our factory helpers to generate fresh, isolated data
    adminToken = await createIsolatedClientAndToken(app);
    topicId = await createIsolatedTopic(app, adminToken);
  });

  afterAll(async () => {
    await app.close();
  });

  describe('Assessments CRUD & Lifecycle', () => {
    it('POST /topics/:topicId/assessments - should create a new assessment', async () => {
      const response = await request(app.getHttpServer())
        .post(`/api/v1/topics/${topicId}/assessments`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          name: 'Math Quiz 101',
          description: 'Basic math questions',
          type: 'QUIZ',
        })
        .expect(201);

      expect(response.body.data).toBeDefined();
      expect(response.body.data.id).toBeDefined();
      expect(response.body.data.status).toBe('DRAFT');
      expect(response.body.data.type).toBe('QUIZ');
      assessmentId = response.body.data.id;
    });

    it('GET /assessments/:id - should fetch the created assessment', async () => {
      const response = await request(app.getHttpServer())
        .get(`/api/v1/assessments/${assessmentId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      expect(response.body.data.id).toBe(assessmentId);
      expect(response.body.data.name).toBe('Math Quiz 101');
    });

    it('PATCH /assessments/:id - should update the assessment', async () => {
      const response = await request(app.getHttpServer())
        .patch(`/api/v1/assessments/${assessmentId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          description: 'Updated basic math questions',
        })
        .expect(200);

      expect(response.body.data.description).toBe(
        'Updated basic math questions',
      );
    });

    it('POST /assessments/:id/questions - should add a question', async () => {
      // First, create a question in the topic
      const qRes = await request(app.getHttpServer())
        .post(`/api/v1/topics/${topicId}/questions`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          type: 'MULTIPLE_CHOICE',
          questionText: 'What is 2 + 2?',
          difficulty: 'EASY',
          options: [
            { id: 'A', text: '3' },
            { id: 'B', text: '4' },
            { id: 'C', text: '5' },
          ],
          correctAnswers: { optionIds: ['B'] },
          points: 10,
        });

      if (qRes.status !== 201) {
        throw new Error(
          `Failed to create question: ${JSON.stringify(qRes.body)}`,
        );
      }

      const createdQuestionId = qRes.body.data.id;

      // Now add it to the assessment
      const response = await request(app.getHttpServer())
        .post(`/api/v1/assessments/${assessmentId}/questions`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          questionId: createdQuestionId,
          points: 10,
        })
        .expect(201);

      expect(response.body.data).toBeDefined();
      expect(response.body.data.id).toBeDefined();
      questionId = response.body.data.id;
    });

    it('PATCH /assessments/:id/settings - should update settings', async () => {
      const response = await request(app.getHttpServer())
        .patch(`/api/v1/assessments/${assessmentId}/settings`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          passMark: 50,
          isShuffle: true,
        })
        .expect(200);

      expect(response.body.data.passMark).toBe(50);
      expect(response.body.data.isShuffle).toBe(true);
    });

    it('POST /assessments/:id/publish - should publish the assessment', async () => {
      const response = await request(app.getHttpServer())
        .post(`/api/v1/assessments/${assessmentId}/publish`)
        .set('Authorization', `Bearer ${adminToken}`)
        .expect(200);

      expect(response.body.data.status).toBe('PUBLISHED');
    });

    it('PATCH /assessments/:id - should fail to update a published assessment', async () => {
      await request(app.getHttpServer())
        .patch(`/api/v1/assessments/${assessmentId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          name: 'Cannot change this',
        })
        .expect(409);
    });
  });
});

import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication, ValidationPipe } from '@nestjs/common';
import request from 'supertest';
import { AppModule } from './../src/app.module';
import { TransformInterceptor } from './../src/common/interceptors/transform.interceptor';
import { ClassSerializerInterceptor } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import Redis from 'ioredis';
import { ThrottlerGuard } from '@nestjs/throttler';
import { AuthThrottlerGuard } from './../src/modules/auth/guards/auth-throttler.guard';

describe('AuthModule (e2e)', () => {
  let app: INestApplication;
  let validClientId: string;
  let validClientSecret: string;
  let suspendedClientId: string;
  let suspendedClientSecret: string;
  let redisClient: Redis;

  beforeAll(async () => {
    process.env.THROTTLE_AUTH_BURST_LIMIT = '2';
    redisClient = new Redis({
      host: process.env.REDIS_HOST || 'localhost',
      port: Number(process.env.REDIS_PORT) || 6379,
    });

    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api/v1');
    app.useGlobalPipes(
      new ValidationPipe({
        whitelist: true,
        transform: true,
      }),
    );
    app.useGlobalInterceptors(
      new TransformInterceptor(),
      new ClassSerializerInterceptor(app.get(Reflector)),
    );
    await app.init();

    // Setup: Create an active client
    const activeRes = await request(app.getHttpServer())
      .post('/api/v1/clients')
      .set('x-admin-api-key', 'test-admin-api-key-12345678901234567890')
      .send({
        name: 'Auth Test Active Client',
        slug: 'auth-active-' + Date.now(),
        allowedOrigins: ['https://acme.com'],
      });
    validClientId = activeRes.body.data.clientId;
    validClientSecret = activeRes.body.data.clientSecret;

    // Setup: Create a suspended client
    const suspendedRes = await request(app.getHttpServer())
      .post('/api/v1/clients')
      .set('x-admin-api-key', 'test-admin-api-key-12345678901234567890')
      .send({
        name: 'Auth Test Suspended Client',
        slug: 'auth-suspended-' + Date.now(),
        allowedOrigins: ['https://acme.com'],
      });
    const suspendedClientDbId = suspendedRes.body.data.id;
    suspendedClientId = suspendedRes.body.data.clientId;
    suspendedClientSecret = suspendedRes.body.data.clientSecret;

    // Suspend the client
    await request(app.getHttpServer())
      .patch(`/api/v1/clients/${suspendedClientDbId}/suspend`)
      .set('x-admin-api-key', 'test-admin-api-key-12345678901234567890')
      .expect(200);
  });

  afterAll(async () => {
    await app.close();
    redisClient.disconnect();
  });

  describe('POST /api/v1/auth/token', () => {
    beforeEach(async () => {
      // Clear all throttle keys from Redis to prevent cascading rate limit failures
      const keys = await redisClient.keys('throttle:*');
      if (keys.length > 0) {
        await redisClient.del(...keys);
      }
    });

    it('should return 400 if grant_type is missing', async () => {
      await request(app.getHttpServer())
        .post('/api/v1/auth/token')
        .send({
          clientId: validClientId,
          clientSecret: validClientSecret,
        })
        .expect(400);
    });

    it('should return 400 if grant_type is invalid', async () => {
      await request(app.getHttpServer())
        .post('/api/v1/auth/token')
        .send({
          clientId: validClientId,
          clientSecret: validClientSecret,
          grant_type: 'password',
        })
        .expect(400);
    });
    it('should return 400 if clientId is missing', async () => {
      await request(app.getHttpServer())
        .post('/api/v1/auth/token')
        .send({
          clientSecret: validClientSecret,
          grant_type: 'client_credentials',
        })
        .expect(400);
    });

    it('should return 400 if clientSecret is missing', async () => {
      await request(app.getHttpServer())
        .post('/api/v1/auth/token')
        .send({
          clientId: validClientId,
          grant_type: 'client_credentials',
        })
        .expect(400);
    });

    it('should return 400 if clientId is not a valid UUID', async () => {
      await request(app.getHttpServer())
        .post('/api/v1/auth/token')
        .send({
          clientId: 'not-a-uuid',
          clientSecret: validClientSecret,
          grant_type: 'client_credentials',
        })
        .expect(400);
    });

    it('should return 401 if client does not exist', async () => {
      await request(app.getHttpServer())
        .post('/api/v1/auth/token')
        .send({
          clientId: '123e4567-e89b-12d3-a456-426614174000', // valid UUID but not in DB
          clientSecret: validClientSecret,
          grant_type: 'client_credentials',
        })
        .expect(401);
    });
    it('should return 401 if client is suspended', async () => {
      await request(app.getHttpServer())
        .post('/api/v1/auth/token')
        .send({
          clientId: suspendedClientId,
          clientSecret: suspendedClientSecret,
          grant_type: 'client_credentials',
        })
        .expect(401);
    });

    it('should return 401 if client credentials are wrong', async () => {
      await request(app.getHttpServer())
        .post('/api/v1/auth/token')
        .send({
          clientId: validClientId,
          clientSecret: 'wrong_secret',
          grant_type: 'client_credentials',
        })
        .expect(401);
    });

    it('should return 200 with access_token if credentials are valid', async () => {
      const response = await request(app.getHttpServer())
        .post('/api/v1/auth/token')
        .send({
          clientId: validClientId,
          clientSecret: validClientSecret,
          grant_type: 'client_credentials',
        })
        .expect(200);

      expect(response.body.success).toBe(true);
      expect(response.body.data).toHaveProperty('access_token');
      expect(response.body.data).toHaveProperty('expires_in');
      expect(response.body.data).toHaveProperty('token_type', 'Bearer');

      // Verify JWT payload
      const token = response.body.data.access_token;
      const payloadBase64 = token.split('.')[1];
      const payloadBuffer = Buffer.from(payloadBase64, 'base64');
      const payload = JSON.parse(payloadBuffer.toString('utf8'));

      expect(payload).toHaveProperty('sub', validClientId);
      expect(payload).toHaveProperty('scopes');
      expect(Array.isArray(payload.scopes)).toBe(true);
    });
  });
});

import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication, ValidationPipe } from '@nestjs/common';
import request from 'supertest';
import { AppModule } from './../src/app.module';
import { TransformInterceptor } from './../src/common/interceptors/transform.interceptor';
import { ClassSerializerInterceptor } from '@nestjs/common';
import { Reflector } from '@nestjs/core';

describe('ClientsModule (e2e)', () => {
  let app: INestApplication;
  let clientId: string;
  let clientDbId: string;
  let clientSecret: string;
  let jwtToken: string;
  let adminToken: string;

  beforeAll(async () => {
    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleFixture.createNestApplication();
    app.setGlobalPrefix('api/v1');
    app.useGlobalPipes(
      new ValidationPipe({
        whitelist: true,
        forbidNonWhitelisted: true,
        transform: true,
      }),
    );
    app.useGlobalInterceptors(
      new ClassSerializerInterceptor(app.get(Reflector)),
      new TransformInterceptor(),
    );
    await app.init();

    // Create an Admin client for testing admin-like operations on other clients
    const adminClientRes = await request(app.getHttpServer())
      .post('/api/v1/clients')
      .set('x-admin-api-key', 'test-admin-api-key-12345678901234567890')
      .send({
        name: 'Admin Test Client',
        slug: `admin-client-${Date.now()}`,
        allowedOrigins: ['https://admin.com'],
      })
      .expect(201);

    const tokenRes = await request(app.getHttpServer())
      .post('/api/v1/auth/token')
      .send({
        clientId: adminClientRes.body.data.clientId,
        clientSecret: adminClientRes.body.data.clientSecret,
        grant_type: 'client_credentials',
      })
      .expect(200);

    adminToken = tokenRes.body.data.access_token;
  });

  afterAll(async () => {
    await app.close();
  });

  describe('/api/v1/clients', () => {
    it('POST - should create a new client (Admin Only)', async () => {
      // Missing API key should fail
      await request(app.getHttpServer())
        .post('/api/v1/clients')
        .send({
          name: 'E2E Test Client',
          slug: `e2e-client-${Date.now()}`,
          allowedOrigins: ['https://acme.com'],
          webhookUrl: 'https://acme.com/webhook',
          webhookSecret: 'my-super-secret',
        })
        .expect(401);

      // With API key should succeed
      const response = await request(app.getHttpServer())
        .post('/api/v1/clients')
        .set('x-admin-api-key', 'test-admin-api-key-12345678901234567890')
        .send({
          name: 'E2E Test Client',
          slug: `e2e-client-${Date.now()}`,
          allowedOrigins: ['https://acme.com'],
          webhookUrl: 'https://acme.com/webhook',
          webhookSecret: 'my-super-secret',
        })
        .expect(201);

      clientDbId = response.body.data.id;
      clientId = response.body.data.clientId;
      clientSecret = response.body.data.clientSecret;
    });

    it('POST /api/v1/auth/token - should get a token for the new client', async () => {
      const response = await request(app.getHttpServer())
        .post('/api/v1/auth/token')
        .send({
          clientId,
          clientSecret,
          grant_type: 'client_credentials',
        })
        .expect(200);

      jwtToken = response.body.data.access_token;
    });

    it('GET - should fail without admin API key', async () => {
      await request(app.getHttpServer()).get('/api/v1/clients').expect(401);
    });

    it('GET - should return array of clients when admin API key is provided', async () => {
      const response = await request(app.getHttpServer())
        .get('/api/v1/clients')
        .set('x-admin-api-key', 'test-admin-api-key-12345678901234567890')
        .expect(200);

      expect(Array.isArray(response.body.data)).toBeTruthy();
      expect(
        response.body.data.some((c: any) => c.id === clientDbId),
      ).toBeTruthy();
    });

    it('GET /:id - should return the specific client (Admin Only)', async () => {
      // Standard JWT should fail
      await request(app.getHttpServer())
        .get(`/api/v1/clients/${clientDbId}`)
        .set('Authorization', `Bearer ${jwtToken}`)
        .expect(401);

      // Admin key should succeed
      const response = await request(app.getHttpServer())
        .get(`/api/v1/clients/${clientDbId}`)
        .set('x-admin-api-key', 'test-admin-api-key-12345678901234567890')
        .expect(200);

      expect(response.body.data.id).toBe(clientDbId);
      expect(response.body.data.name).toBe('E2E Test Client');
    });

    it('GET /me - should return own client profile', async () => {
      const response = await request(app.getHttpServer())
        .get(`/api/v1/clients/me`)
        .set('Authorization', `Bearer ${jwtToken}`)
        .expect(200);

      expect(response.body.data.id).toBe(clientDbId);
      expect(response.body.data.name).toBe('E2E Test Client');
    });

    it('PATCH /me - should update own client configuration', async () => {
      const response = await request(app.getHttpServer())
        .patch(`/api/v1/clients/me`)
        .set('Authorization', `Bearer ${jwtToken}`)
        .send({
          webhookUrl: 'https://own-update.com/webhook',
        })
        .expect(200);

      expect(response.body.data.webhookUrl).toBe(
        'https://own-update.com/webhook',
      );
    });

    it('PATCH /:id - should update the client name and webhook settings (Admin Only)', async () => {
      const response = await request(app.getHttpServer())
        .patch(`/api/v1/clients/${clientDbId}`)
        .set('x-admin-api-key', 'test-admin-api-key-12345678901234567890')
        .send({
          name: 'Updated E2E Client',
          webhookUrl: 'https://new-acme.com/webhook',
          webhookSecret: 'new-secret',
        })
        .expect(200);

      expect(response.body.data.name).toBe('Updated E2E Client');
      expect(response.body.data.webhookUrl).toBe(
        'https://new-acme.com/webhook',
      );
      expect(response.body.data.webhookSecret).toBeUndefined();
    });

    it('PATCH /:id/suspend - should suspend the client', async () => {
      const response = await request(app.getHttpServer())
        .patch(`/api/v1/clients/${clientDbId}/suspend`)
        .set('x-admin-api-key', 'test-admin-api-key-12345678901234567890')
        .expect(200);

      expect(response.body.data.isActive).toBe(false);
    });

    it('PATCH /:id/activate - should activate the client', async () => {
      const response = await request(app.getHttpServer())
        .patch(`/api/v1/clients/${clientDbId}/activate`)
        .set('x-admin-api-key', 'test-admin-api-key-12345678901234567890')
        .expect(200);

      expect(response.body.data.isActive).toBe(true);
    });

    it('POST /:id/rotate-secret - should rotate the secret', async () => {
      // Wait for authBurst limit window (1000ms) to reset from earlier token requests
      await new Promise((r) => setTimeout(r, 1100));

      const response = await request(app.getHttpServer())
        .post(`/api/v1/clients/${clientDbId}/rotate-secret`)
        .set('x-admin-api-key', 'test-admin-api-key-12345678901234567890')
        .expect(200);

      expect(response.body.data.clientSecret).toBeDefined();
      expect(response.body.data.clientSecret).not.toBe(clientSecret);

      const newSecret = response.body.data.clientSecret;

      // Try to get token with old secret -> should fail (this is request 2/2 in 1s burst window)
      await request(app.getHttpServer())
        .post('/api/v1/auth/token')
        .send({
          clientId,
          clientSecret,
          grant_type: 'client_credentials',
        })
        .expect(401);

      // Wait for authBurst limit window (1000ms) to reset
      await new Promise((r) => setTimeout(r, 1100));

      // Try to get token with new secret -> should succeed
      await request(app.getHttpServer())
        .post('/api/v1/auth/token')
        .send({
          clientId,
          clientSecret: newSecret,
          grant_type: 'client_credentials',
        })
        .expect(200);
    });
  });
});

import { Test, TestingModule } from '@nestjs/testing';
import { INestApplication } from '@nestjs/common';
import { io, Socket } from 'socket.io-client';
import { AppModule } from './../src/app.module';
import { RealtimeEvents } from './../src/modules/realtime/constants/realtime.events';
import { RoomRole } from './../src/modules/realtime/dto/join-room.dto';
import { IoAdapter } from '@nestjs/platform-socket.io';
import Redis from 'ioredis';

import { RealtimeSessionService } from './../src/modules/realtime/services/realtime-session.service';

describe('RealtimeGateway (e2e)', () => {
  let app: INestApplication;
  let hostSocket: Socket;
  let participantSocket: Socket;
  let serverUrl: string;
  let redisClient: Redis;
  let sessionServiceMock: Partial<RealtimeSessionService>;
  const assessmentId = 'e2e-assessment-uuid';
  const participantId = 'e2e-participant-1';

  beforeAll(async () => {
    redisClient = new Redis({
      host: process.env.REDIS_HOST || 'localhost',
      port: Number(process.env.REDIS_PORT) || 6379,
    });

    sessionServiceMock = {
      redis: {
        getSession: jest.fn().mockResolvedValue({
          hostSocketId: 'host-socket-id',
          status: 'active',
          currentQuestionId: 'q-0',
        }),
        getMembers: jest.fn().mockResolvedValue([
          {
            socketId: 'test-participant-socket',
            role: 'participant',
            participantId,
          },
        ]),
        getParticipantRank: jest
          .fn()
          .mockResolvedValue({ rank: 1, score: 1000 }),
      } as any,
      joinRoom: jest.fn().mockResolvedValue({
        count: 1,
        participants: [],
      }),
      startQuestion: jest
        .fn()
        .mockResolvedValue({ questionNumber: 1, totalQuestions: 5 }),
      revealAnswers: jest.fn().mockResolvedValue(true),
      submitAnswer: jest
        .fn()
        .mockResolvedValue({ totalAnswered: 1, totalParticipants: 1 }),
      endQuestion: jest
        .fn()
        .mockResolvedValue({ correctAnswer: { optionId: 'A' }, stats: {} }),
      getRankData: jest.fn().mockResolvedValue({ leaderboard: [] }),
    };

    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [AppModule],
    })
      .overrideProvider(RealtimeSessionService)
      .useValue(sessionServiceMock)
      .compile();

    app = moduleFixture.createNestApplication();
    app.useWebSocketAdapter(new IoAdapter(app));
    await app.init();
    await app.listen(0);

    const server = app.getHttpServer();
    const port = server.address().port;
    serverUrl = `http://127.0.0.1:${port}/realtime`;
  });

  afterAll(async () => {
    if (hostSocket) hostSocket.disconnect();
    if (participantSocket) participantSocket.disconnect();
    await redisClient.disconnect();
    await app.close();
  });

  afterEach(async () => {
    if (hostSocket) hostSocket.removeAllListeners();
    if (participantSocket) participantSocket.removeAllListeners();
  });

  beforeEach(async () => {
    // Clean up Redis before each test
    const keys = await redisClient.keys(`realtime:*`);
    if (keys.length > 0) {
      await redisClient.del(...keys);
    }
  });

  it('should allow a host to join a room', async () => {
    hostSocket = io(serverUrl, {
      auth: { clientId: 'e2e-client' },
      transports: ['websocket'],
    });

    const connectPromise = new Promise<void>((resolve, reject) => {
      hostSocket.on('connect', () => resolve());
      hostSocket.on('connect_error', (err) =>
        reject(new Error('Connect Error: ' + err.message)),
      );
    });

    await connectPromise;

    const roomUpdatePromise = new Promise<any>((resolve) => {
      hostSocket.on(RealtimeEvents.ROOM_UPDATE, (data) => resolve(data));
    });

    hostSocket.emit(RealtimeEvents.JOIN_ROOM, {
      roomId: assessmentId,
      role: RoomRole.HOST,
    });

    const data = await roomUpdatePromise;
    expect(data).toBeDefined();
    expect(data.count).toBe(1);
  });

  it('should broadcast ROOM_UPDATE when a participant joins', async () => {
    sessionServiceMock.joinRoom = jest.fn().mockResolvedValue({
      count: 2,
      participants: [
        { id: participantId, name: 'Test User', status: 'connected' },
      ],
    });

    participantSocket = io(serverUrl, {
      auth: { clientId: 'e2e-client' },
      transports: ['websocket'],
    });

    const connectPromise = new Promise<void>((resolve, reject) => {
      participantSocket.on('connect', () => resolve());
      participantSocket.on('connect_error', (err) =>
        reject(new Error('Connect Error: ' + err.message)),
      );
    });

    await connectPromise;

    const roomUpdatePromise = new Promise<any>((resolve) => {
      hostSocket.on(RealtimeEvents.ROOM_UPDATE, (data) => resolve(data));
    });

    participantSocket.emit(RealtimeEvents.JOIN_ROOM, {
      roomId: assessmentId,
      role: RoomRole.PARTICIPANT,
      participantId: participantId,
    });

    const data = await roomUpdatePromise;
    expect(data.count).toBe(2);
    expect(data.participants.some((p: any) => p.id === participantId)).toBe(
      true,
    );
  });

  it('should start the session when host emits START_Q', async () => {
    const sessionStartedPromise = new Promise<any>((resolve) => {
      participantSocket.on(RealtimeEvents.NEW_QUESTION, (data) =>
        resolve(data),
      );
    });

    hostSocket.emit(RealtimeEvents.START_Q, {
      roomId: assessmentId,
      questionId: 'q-1',
      durationSeconds: 30,
    });

    const data = await sessionStartedPromise;
    expect(data.questionNumber).toBe(1);
  });

  it('should allow participant to submit an answer and broadcast RESULTS when host reveals', async () => {
    // Make sure the mock returns the actual host socket ID
    sessionServiceMock.redis.getSession = jest.fn().mockResolvedValue({
      hostSocketId: hostSocket.id,
      status: 'active',
      currentQuestionId: 'q-1',
    });

    participantSocket.emit(RealtimeEvents.SUBMIT_ANS, {
      roomId: assessmentId,
      participantId: participantId,
      questionId: 'q-1',
      answers: ['A'],
    });

    const resultsPromise = new Promise<any>((resolve) => {
      participantSocket.on(RealtimeEvents.Q_RESULTS, (data) => resolve(data));
    });

    // Wait slightly to ensure answer registered
    await new Promise((r) => setTimeout(r, 50));

    hostSocket.emit(RealtimeEvents.REVEAL_ANSWERS, {
      roomId: assessmentId,
    });

    const data = await resultsPromise;
